import { StyleSheet, Text, View } from "react-native";
import { SafeAreaView } from "react-native-safe-area-context";
import { MAP_INK, MapView } from "@/lib/map";
import { space, type as typeScale } from "@/lib/ui";

/** The Kip Map: Newcastle full screen, with the title floating over it. */
export function CityScreen() {
  return (
    <View style={styles.root}>
      <MapView style={StyleSheet.absoluteFill} />
      <SafeAreaView edges={["top"]} style={styles.header}>
        <Text style={[typeScale.title, styles.title]}>Kip Map</Text>
      </SafeAreaView>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1 },
  // The title floats over the map and lets touches through to it.
  header: {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    paddingHorizontal: space.md,
    pointerEvents: "box-none",
  },
  // Map ink, not the theme's text colour: the basemap stays light in dark mode too.
  title: { color: MAP_INK },
});
import type { StyleProp, ViewStyle } from "react-native";

/** [longitude, latitude] */
export type MapPosition = [number, number];

export type MapPointGeometry = {
  type: "Point";
  coordinates: MapPosition;
};

export type MapLineGeometry = {
  type: "LineString";
  coordinates: MapPosition[];
};

/** Rings are [longitude, latitude] positions. The first ring is the outer boundary. */
export type MapPolygonGeometry = {
  type: "Polygon";
  coordinates: MapPosition[][];
};

export type MapGeometry = MapPointGeometry | MapLineGeometry | MapPolygonGeometry;

export type MapFeatureProperties = Record<string, string | number | boolean | null>;

/**
 * One drawn feature. `id` is what selection reports.
 * Feature code builds these values. It does not import Mapbox or MapLibre.
 */
export type MapFeature = {
  type: "Feature";
  id: string;
  geometry: MapGeometry;
  properties?: MapFeatureProperties | null;
};

export type MapFeatureCollection = {
  type: "FeatureCollection";
  features: MapFeature[];
};

export type MapCamera = {
  center: MapPosition;
  zoom: number;
};

export type MapSelection = {
  id: string;
};

export type MapProps = {
  /** [longitude, latitude]; defaults to Newcastle */
  center?: MapPosition;
  zoom?: number;
  style?: StyleProp<ViewStyle>;
  /** Points, lines and polygons drawn on top of the basemap. */
  features?: MapFeatureCollection;
  /** Cluster point features. Lines and polygons are never clustered. */
  cluster?: boolean;
  /** Feature id to draw as selected. */
  selectedId?: string | null;
  onSelect?: (selection: MapSelection | null) => void;
  onCameraChange?: (camera: MapCamera) => void;
};
// Metro picks Map.web.tsx (Mapbox GL JS) on web and Map.native.tsx (@rnmapbox/maps) on iOS.
// TypeScript resolves the native file through `moduleSuffixes`; both files are type-checked.
// Feature code imports this module and does not import either Mapbox SDK.
export { MapView } from "./Map";
export { MAP_INK, MAPBOX_STYLE, NEWCASTLE } from "./style";
export type {
  MapCamera,
  MapFeature,
  MapFeatureCollection,
  MapFeatureProperties,
  MapGeometry,
  MapPosition,
  MapProps,
  MapSelection,
} from "./types";
